// AXI-64: formal property harness for the AXI4-Lite slave generated by
// compile_axi_lite_wrapper (sw/kpol-ref/kpol_reference.py).
// Properties P1..P6 are pre-registered in Issue #64 (comment 6820456204).
// The generated DUT is instantiated unmodified; the harness only observes it.

module axi64_formal (
    input logic        clk,
    input logic        aresetn,
    input logic [5:0]  awaddr,
    input logic [2:0]  awprot,
    input logic        awvalid,
    input logic [31:0] wdata,
    input logic [3:0]  wstrb,
    input logic        wvalid,
    input logic        bready,
    input logic [5:0]  araddr,
    input logic [2:0]  arprot,
    input logic        arvalid,
    input logic        rready
);
    logic        awready, wready, bvalid, arready, rvalid;
    logic [1:0]  bresp, rresp;
    logic [31:0] rdata;

    km_aximodule_axi_lite_slave dut (
        .s_axi_aclk(clk), .s_axi_aresetn(aresetn),
        .s_axi_awaddr(awaddr), .s_axi_awprot(awprot),
        .s_axi_awvalid(awvalid), .s_axi_awready(awready),
        .s_axi_wdata(wdata), .s_axi_wstrb(wstrb),
        .s_axi_wvalid(wvalid), .s_axi_wready(wready),
        .s_axi_bresp(bresp), .s_axi_bvalid(bvalid), .s_axi_bready(bready),
        .s_axi_araddr(araddr), .s_axi_arprot(arprot),
        .s_axi_arvalid(arvalid), .s_axi_arready(arready),
        .s_axi_rdata(rdata), .s_axi_rresp(rresp),
        .s_axi_rvalid(rvalid), .s_axi_rready(rready)
    );

    wire aw_hs = awvalid && awready;
    wire w_hs  = wvalid  && wready;
    wire b_hs  = bvalid  && bready;
    wire ar_hs = arvalid && arready;
    wire r_hs  = rvalid  && rready;

    logic past_valid = 1'b0;
    logic p_rst, p_awstall, p_wstall, p_arstall, p_bstall, p_rstall;
    logic [5:0]  p_awaddr, p_araddr;
    logic [2:0]  p_awprot, p_arprot;
    logic [31:0] p_wdata, p_rdata;
    logic [3:0]  p_wstrb;
    logic [1:0]  p_bresp, p_rresp;

    always @(posedge clk) begin
        past_valid <= 1'b1;
        p_rst      <= !aresetn;
        p_awstall  <= awvalid && !awready;
        p_wstall   <= wvalid  && !wready;
        p_arstall  <= arvalid && !arready;
        p_bstall   <= bvalid  && !bready;
        p_rstall   <= rvalid  && !rready;
        p_awaddr <= awaddr; p_awprot <= awprot;
        p_araddr <= araddr; p_arprot <= arprot;
        p_wdata  <= wdata;  p_wstrb  <= wstrb;
        p_bresp  <= bresp;  p_rresp  <= rresp; p_rdata <= rdata;
    end

    // ---- Master assumptions (AXI4-Lite master rules) ----
    always @(*) begin
        if (!past_valid) assume (!aresetn);
        if (!aresetn) assume (!awvalid && !wvalid && !arvalid);
        if (past_valid && !p_rst && aresetn) begin
            if (p_awstall) assume (awvalid && awaddr == p_awaddr && awprot == p_awprot);
            if (p_wstall)  assume (wvalid && wdata == p_wdata && wstrb == p_wstrb);
            if (p_arstall) assume (arvalid && araddr == p_araddr && arprot == p_arprot);
        end
    end

    // ---- Handshake accounting (P3, P4) ----
    logic [2:0] na, nw;   // #AW - #B, #W - #B
    logic [1:0] nr;       // #AR - #R
    always @(posedge clk) begin
        if (!aresetn) begin
            na <= 0; nw <= 0; nr <= 0;
        end else begin
            na <= na + aw_hs - b_hs;
            nw <= nw + w_hs  - b_hs;
            nr <= nr + ar_hs - r_hs;
        end
    end
    wire [2:0] nmin = (na < nw) ? na : nw;

    // ---- Shadow register model (P5): address from AW, byte-wise WSTRB ----
    logic [31:0] sh0, sh1, sh2;
    logic        pa_v, pw_v;
    logic [5:0]  pa_addr;
    logic [31:0] pw_data;
    logic [3:0]  pw_strb;
    logic        exp_chk;
    logic [31:0] exp_data;

    wire        c_aw_v = pa_v || aw_hs;
    wire        c_w_v  = pw_v || w_hs;
    wire [5:0]  c_addr = pa_v ? pa_addr : awaddr;
    wire [31:0] c_data = pw_v ? pw_data : wdata;
    wire [3:0]  c_strb = pw_v ? pw_strb : wstrb;

    function automatic [31:0] merge(input [31:0] o, input [31:0] n, input [3:0] s);
        merge = {s[3] ? n[31:24] : o[31:24], s[2] ? n[23:16] : o[23:16],
                 s[1] ? n[15:8]  : o[15:8],  s[0] ? n[7:0]   : o[7:0]};
    endfunction

    always @(posedge clk) begin
        if (!aresetn) begin
            sh0 <= 0; sh1 <= 0; sh2 <= 0;
            pa_v <= 0; pw_v <= 0; exp_chk <= 0; exp_data <= 0;
        end else begin
            if (ar_hs) begin
                exp_chk  <= (araddr[5:2] != 4'h4);
                exp_data <= (araddr[5:2] == 4'h0) ? sh0 :
                            (araddr[5:2] == 4'h1) ? sh1 :
                            (araddr[5:2] == 4'h2) ? sh2 : 32'h0;
            end
            if (c_aw_v && c_w_v) begin
                case (c_addr[5:2])
                    4'h0: sh0 <= merge(sh0, c_data, c_strb);
                    4'h1: sh1 <= merge(sh1, c_data, c_strb);
                    4'h2: sh2 <= merge(sh2, c_data, c_strb);
                    default: ;
                endcase
                pa_v <= 0; pw_v <= 0;
            end else begin
                if (aw_hs) begin pa_v <= 1; pa_addr <= awaddr; end
                if (w_hs)  begin pw_v <= 1; pw_data <= wdata; pw_strb <= wstrb; end
            end
        end
    end

    // ---- Slave properties ----
    always @(*) begin
        if (past_valid && aresetn && !p_rst) begin
            P1_b_stable:  assert (!p_bstall || (bvalid && bresp == p_bresp));
            P2_r_stable:  assert (!p_rstall || (rvalid && rdata == p_rdata && rresp == p_rresp));
        end
        if (past_valid && p_rst) begin
            P6_reset:     assert (!bvalid && !rvalid);
        end
        if (past_valid && aresetn && !p_rst) begin
            P3_b_count:   assert (na <= 3'd2 && nw <= 3'd2 && nmin == {2'b0, bvalid});
            P4_r_count:   assert (nr <= 2'd1 && nr == {1'b0, rvalid});
            P5_data:      assert (!(rvalid && exp_chk) || rdata == exp_data);
        end
    end

    // ---- Coverage of the pre-registered scenarios ----
    always @(*) begin
        if (aresetn && past_valid && !p_rst) begin
            C1_aw_before_w:   cover (pa_v && !pw_v && w_hs);
            C2_w_before_aw:   cover (pw_v && !pa_v && aw_hs);
            C3_simultaneous:  cover (aw_hs && w_hs && !pa_v && !pw_v);
            C4_b_backpressure: cover (p_bstall && bvalid);
            C5_r_backpressure: cover (p_rstall && rvalid);
            C6_partial_strobe: cover (w_hs && wstrb != 4'h0 && wstrb != 4'hF);
            C7_read_written:  cover (rvalid && exp_chk && rdata != 0 && rdata != 32'hFFFFFFFF);
        end
    end
endmodule
